import cn from 'classnames';

import TabToggler from './components/tab-toggler';
import TabItem from './components/tab-item';
import Teaser from '../teaser/teaser';
import Table from '../table/table';

import { TabImageItem, TabsProps, TabTextItem } from './tabs.types';
import { TableProps } from '../table/table.types';
import { TeaserProps } from '../teaser/teaser.types';
import EmbedVideo from '../embed-video/embed-video';
import { EmbedVideoProps } from '../embed-video/embed-video.type';

import './tabs.scss';

export function Tabs({
  id,
  className,
  ':itemsOrder': itemsOrder,
  ':items': items,
  activeItem,
  useResponsiveSelect,
  useWindowResizeType = true,
  useResponsiveType = 'window',
  children,
}: TabsProps) {
  return (
    <div
      className={cn('tabs panelcontainer', className, {
        'ds-brand-responsive-select-run-js': useResponsiveSelect,
        'ds-window-resize-type': useWindowResizeType && useResponsiveSelect,
        'ds-container-query': useResponsiveType === 'container',
      })}
    >
      <div id={id} className="cmp-tabs" data-cmp-data-layer="" data-placeholder-text="false">
        <ol role="tablist" className="cmp-tabs__tablist" aria-multiselectable="false">
          {itemsOrder.map((itemOrder, index) => (
            <TabToggler
              key={`${id}-item-${index}-tab`}
              id={`${id}-item-${index}-tab`}
              isActive={activeItem === itemOrder}
              text={items[itemOrder]['cq:panelTitle']}
              ariaControl={`${id}-item-${index}-tabpanel`}
            />
          ))}
        </ol>
        {itemsOrder.map((itemOrder, index) => (
          <TabItem
            key={index}
            id={`${id}-item-${index}-tabpanel`}
            ariaLabelledBy={`${id}-item-${index}-tab`}
            tabIndex={activeItem === itemOrder ? 1 : 0}
            isActive={activeItem === itemOrder}
          >
            {children ? (
              children
            ) : (
              <>
                {items[itemOrder][':itemsOrder'].map((componentName, index) => {
                  const props = items[itemOrder][':items'][componentName];
                  const componentClassName = items[itemOrder].columnClassNames[componentName];

                  if (componentName === 'image') {
                    const componentProps = props as TabImageItem;
                    return (
                      <div key={index} className={cn('image', componentClassName)}>
                        <div
                          data-asset-id={componentProps?.uuid}
                          id={componentProps?.id}
                          data-cmp-data-layer=""
                          className="cmp-image"
                          itemScope
                          itemType="http://schema.org/ImageObject"
                        >
                          <img
                            srcSet={componentProps?.srcset}
                            loading="lazy"
                            className="cmp-image__image"
                            itemProp="contentUrl"
                            width="850"
                            height="509"
                            alt={componentProps?.title}
                            title={componentProps?.title}
                          />
                          <meta itemProp="caption" content={componentProps?.title} />
                        </div>
                      </div>
                    );
                  }
                  if (componentName === 'text') {
                    const componentProps = props as TabTextItem;
                    return (
                      <div key={index} className={cn('text', componentClassName)}>
                        {componentProps?.richText ? (
                          <div
                            data-cmp-data-layer=""
                            id={componentProps?.id}
                            className="cmp-text"
                            dangerouslySetInnerHTML={{ __html: componentProps?.text || '' }}
                          />
                        ) : (
                          <div data-cmp-data-layer="" id={componentProps?.id} className="cmp-text">
                            <p>{componentProps?.text}</p>
                          </div>
                        )}
                      </div>
                    );
                  }
                  if (componentName === 'teaser') {
                    const componentProps = props as TeaserProps;
                    return (
                      <Teaser
                        key={index}
                        {...componentProps}
                        className={cn(componentProps.className, componentClassName)}
                      />
                    );
                  }
                  if (componentName === 'table') {
                    const componentProps = props as TableProps;
                    return (
                      <Table
                        key={index}
                        {...componentProps}
                        className={cn(componentProps.className, componentClassName)}
                      />
                    );
                  }
                  if (componentName === 'embed-video') {
                    const componentProps = props as EmbedVideoProps;
                    return (
                      <EmbedVideo
                        key={index}
                        {...componentProps}
                        className={cn(componentProps.className, componentClassName)}
                      />
                    );
                  }
                  if (componentName === 'custom-component') {
                    return <>{props}</>;
                  }
                })}
              </>
            )}
          </TabItem>
        ))}
      </div>
    </div>
  );
}

export default Tabs;
