import { ReactNode } from 'react';
import cn from 'classnames';

type TabItemProps = {
  id: string;
  ariaLabelledBy: string;
  tabIndex: number;
  isActive: boolean;
  children: ReactNode;
};

function TabItem({ id, ariaLabelledBy, tabIndex, isActive, children }: TabItemProps) {
  return (
    <div
      id={id}
      role="tabpanel"
      aria-labelledby={ariaLabelledBy}
      tabIndex={tabIndex}
      className={cn('cmp-tabs__tabpanel', { 'cmp-tabs__tabpanel--active': isActive })}
      data-cmp-hook-tabs="tabpanel"
      data-cmp-data-layer=""
      aria-hidden={isActive ? 'false' : 'true'}
    >
      <div className="responsivegrid">
        <div className="aem-Grid aem-Grid--12 aem-Grid--default--12">{children}</div>
      </div>
    </div>
  );
}

export default TabItem;
